<?php if (!defined('__TYPECHO_ROOT_DIR__')) exit; $this->need('header.php'); ?>
<?php if ($this->is('search')): ?><div class="section-label"><span>⌕ 搜索结果：<?php echo htmlspecialchars($this->getArchiveTitle(), ENT_QUOTES, 'UTF-8'); ?></span><span><?php echo (int)$this->getTotal(); ?> 篇文章</span></div><?php else: ?><div class="section-label"><span>▦ 冒险日志</span><span>EXPLORATION LOG</span></div><?php endif; ?><?php if ($this->is('search') && !$this->getTotal()): ?><div class="post-card">没有找到匹配的冒险日志，请尝试其他关键词。</div><?php endif; ?>
<?php if ($this->getTotalPage() > 1): ?><div class="pagination pagination-top"><?php $this->pageNav('« 上一页','下一页 »', 2, '...', array('wrapTag'=>'nav','wrapClass'=>'page-nav')); ?></div><?php endif; ?>
<?php while($this->next()): ?><article class="post-card"><div class="post-top"><span class="post-icon">✦</span><div><div class="meta"><?php $this->date('Y-m-d'); ?> · <?php $this->category(' / '); ?></div><h2><a href="<?php $this->permalink(); ?>"><?php $this->title(); ?></a></h2></div></div><div class="excerpt"><?php $this->excerpt(220, '…'); ?></div><div class="card-bottom"><span>☷ <?php $this->commentsNum('0 条留言','1 条留言','%d 条留言'); ?></span><a class="pixel-btn" href="<?php $this->permalink(); ?>">继续阅读 →</a></div></article><?php endwhile; ?>
<div class="pagination"><?php $this->pageNav('« 上一页','下一页 »', 2, '...', array('wrapTag'=>'nav','wrapClass'=>'page-nav')); ?></div>
<?php $this->need('footer.php'); ?>
